'use strict';
const RealmUI=(()=>{
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function panel(s){const d=RealmLife.get(s.kingdom);if(!d)return '';return `<section class="panel realm-life-panel"><div><small>ชีวิตในอาณาจักรนี้</small><h3>${esc(d.name)}</h3><p>${esc(Ecology.native(s)?d.nature:d.daily)}</p></div><button class="secondary" data-realm-detail="${d.id}">รู้จักถิ่นนี้ →</button></section>`}
 function open(id){const k=Number(id),d=RealmLife.get(k),detail=WorldMap.detail(k),clans=HumanOrigins.clans.filter(c=>c.realm===k&&WorldHistory.founding(c)<=WorldTimeline.year(state)).map(c=>WorldHistory.house(c,WorldTimeline.year(state)));modal(`<section class="realm-dossier"><span class="eyebrow">อาณาจักร ${k+1} / ${KINGDOMS.length}</span><h2>${esc(detail.name)}</h2><p>${esc(detail.title)}</p><dl><dt>ภูมิประเทศและการตั้งถิ่น</dt><dd>${esc(detail.terrain)}</dd><dt>แหล่งดำรงชีวิตและเศรษฐกิจ</dt><dd>${esc(d?.resource||detail.water)}</dd><dt>ค่าครองชีพเทียบฐาน</dt><dd>${Math.round(Economy.regions[k]*100)}% · 1 ทอง = 1 USD</dd><dt>ข่าวที่คนในถิ่นกำลังเผชิญ</dt><dd>${esc(d?.pressure||detail.rumor)}</dd>${d?`<dt>ธรรมเนียมท้องถิ่น</dt><dd>${esc(d.custom)}</dd><dt>สิ่งที่เผ่าอาศัยตามธรรมชาติเผชิญ</dt><dd>${esc(d.nature)}</dd>`:''}<dt>อาณาจักรที่มีทางเชื่อม</dt><dd>${detail.neighbors.map(n=>esc(KINGDOMS[n.index][0])+' · '+esc(n.mode)).join('<br>')}</dd></dl><h3>ตระกูลมนุษย์และสถาบันในถิ่น</h3><p>ตระกูลเหล่านี้เป็นโครงสร้างสังคมมนุษย์ เผ่าอื่นยังมีฝูง รัง และกลุ่มตามวิถีของตน</p><div class="realm-house-list">${clans.map(c=>`<article><b>${esc(c.name)}</b><small>${esc(HumanOrigins.types.find(t=>t.id===c.type).label)}</small><p>${esc(c.motto)}</p></article>`).join('')}</div></section>`)}
 function bind(){document.querySelectorAll('[data-realm-detail]').forEach(b=>b.onclick=()=>open(b.dataset.realmDetail))}
 return {panel,open,bind};
})();
